// Brutal.ImGui's flat C API for RimWorld 1.7 (Waylith), over Dear ImGui 1.92.2-docking.
//
// The game's libimgui.so is Dear ImGui built with IMGUI_DISABLE_OBSOLETE_FUNCTIONS and
// IMGUI_USE_WCHAR32 (sizeof(ImGuiIO) 3064, ImGuiStyle 1276, ImDrawVert 20, ImDrawIdx 2 — read from its
// DebugCheckVersionAndDataLayout; ImWchar 32-bit from its mangled names) plus ~1150 extern "C"
// wrappers named by Brutal's generator. The managed side reads ImGui structs directly, so the same
// options are set here (CMake) and checked at compile time below. imgui_brutal.cpp is generated by
// tools/rimworld17/gen_imgui.py from the P/Invoke signatures in Brutal.ImGui.dll.
#pragma once
#include <stdint.h>
#include <stddef.h>
#include <new>
#include <type_traits>
#include "imgui.h"
#include "imgui_internal.h"

static_assert(sizeof(ImGuiIO) == 3064, "ImGuiIO layout differs from the game's");
static_assert(sizeof(ImGuiStyle) == 1276, "ImGuiStyle layout differs from the game's");
static_assert(sizeof(ImDrawVert) == 20 && sizeof(ImDrawIdx) == 2, "draw data layout differs");
static_assert(sizeof(ImWchar) == 4, "ImWchar must be 32-bit (IMGUI_USE_WCHAR32)");

#define RDW __attribute__((visibility("default")))

#include <stdlib.h>

// Text size (RIMDROID_TEXT_SCALE, set by ClrActivity; 1 when unset): RimWorld 1.7 lays out and draws
// its text itself from the glyphs of the baked font it asks for (ImFont_GetFontBaked) and measures with
// ImFont_CalcTextSizeA; both wrappers ask ImGui for that size times this factor, so the letters grow
// while windows and boxes keep their size. Clamped to 0.5..2.
static inline float rd_text_scale() {
    static float scale = [] {
        const char* e = getenv("RIMDROID_TEXT_SCALE");
        float v = e ? (float)atof(e) : 1.0f;
        return v >= 0.5f && v <= 2.0f ? v : 1.0f;
    }();
    return scale;
}

// A vector argument the managed side passes by pointer: becomes T& or T* as the callee wants, and
// float* for ImVec2/ImVec4 (DragFloat2's float v[2], ColorEdit4's float col[4]).
template <typename T> struct Ref {
    const T* p;
    operator T&() const { return *const_cast<T*>(p); }
    operator T*() const { return const_cast<T*>(p); }
    template <typename U = T, typename std::enable_if<std::is_same<U, ImVec2>::value || std::is_same<U, ImVec4>::value, int>::type = 0>
    operator float*() const { return reinterpret_cast<float*>(const_cast<T*>(p)); }
};

// A pointer to a plain value: T* or T& as the callee wants.
template <typename T> struct Ptr {
    T* p;
    operator T*() const { return p; }
    operator T&() const { return *p; }
};

// An integer the managed side uses for callbacks and getters: becomes whatever pointer type the
// callee takes (function pointers included), or stays an integer.
struct Any {
    intptr_t v;
    template <typename T> operator T() const {
        if constexpr (std::is_pointer<T>::value) return reinterpret_cast<T>(v);
        else return static_cast<T>(v);
    }
};
